PR pulls value look up into the default factory where possible.

This is done only in the @pre_init decorator where it shouldn't break anything.


# Migration

```
engine marzano(0.1)
language python

function trim1($x) js {
    return $x.text.slice(1, -1)
}

or {


`values[$Q] = get_from_dict_or_env($f, $Q, $ENV)` as $assign where {
    $X = trim1($Q),
    $assign <: within $F where {
        $F <: decorated_definition(),
        $F <: contains `@pre_init`,
    },
    $assign <: within class_definition($body),
    $body <: block($statements),    
    $statements <: some bubble($ENV, $X) assignment(left=$x, right=$y, type=$t) as $A where {
        $x <: $X,
        or {
            $y <: `Field($args)` where {
                $args <: contains `default=None` => `default_factory=from_env($ENV)`,
            },
            $y <: `None` => `Field(default_factory=from_env($ENV))`,
            $y <: `Field($z)` => `Field($z, default_factory=from_env($ENV))`,
            $y <: `$Q` => `Field(default_factory=from_env($ENV, defaul=$Q))`,
        }
    },
    $assign => .,
    add_import(source="langchain_core.utils", name="from_env"),
},



`values[$Q] = get_from_dict_or_env($f, $Q, $ENV, $DEFAULT)` as $assign where {
    $X = trim1($Q),
    $assign <: within $F where {
        $F <: decorated_definition(),
        $F <: contains `@pre_init`,
    },

    $assign <: within class_definition($body),
    $body <: block($statements),

    $DEFAULT <: contains or {
        `default=$default_value`,
        `$default_value`
    },
    $statements <: some bubble($ENV, $X, $default_value) assignment(left=$x, right=$y, type=$t) as $A where {
        $x <: $X,
        or {
            $y <: `Field($args)` where {
                $args <: contains or {`default=$default_value`, `default=None`} => `default_factory=from_env($ENV, default=$default_value)`,
            },
            $y <: `None` => `Field(default_factory=from_env($ENV, default=$default_value))`,
            $y <: `Field($z)` => `Field(default_factory=from_env($z, $ENV, default=$default_value))`,
        }
    },
    $assign => .,
    add_import(source="langchain_core.utils", name="from_env"),
}

}
