```python
import os
import re
import json

def add_or_update_frontmatter_mdx(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        content = file.read()

    frontmatter_pattern = re.compile(r'^---\s+(.*?)\s+---', re.DOTALL | re.MULTILINE)
    frontmatter_match = frontmatter_pattern.search(content)

    if frontmatter_match:
        frontmatter_content = frontmatter_match.group(1)
        if 'displayed_sidebar:' not in frontmatter_content:
            updated_frontmatter = frontmatter_content.rstrip() + '\ndisplayed_sidebar: docs'
            updated_content = frontmatter_pattern.sub(f'---\n{updated_frontmatter}\n---', content, count=1)
        else:
            updated_content = content
    else:
        updated_content = f'---\ndisplayed_sidebar: docs\n---\n{content}'

    with open(file_path, 'w', encoding='utf-8') as file:
        file.write(updated_content)

def add_or_update_frontmatter_ipynb(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        notebook = json.load(file)

    frontmatter_cell = {
        "cell_type": "raw",
        "metadata": {},
        "source": [
            "---\ndisplayed_sidebar: docs\n---"
        ]
    }

    frontmatter_found = False
    for cell in notebook['cells']:
        if cell['cell_type'] == 'raw':
            if '---' in cell['source'][0]:
                if 'displayed_sidebar:' not in cell['source'][0]:
                    cell['source'][0] = cell['source'][0].rstrip() + '\ndisplayed_sidebar: docs\n'
                frontmatter_found = True
                break

    if not frontmatter_found:
        notebook['cells'].insert(0, frontmatter_cell)

    with open(file_path, 'w', encoding='utf-8') as file:
        json.dump(notebook, file, ensure_ascii=False, sort_keys=True, indent=1)

def main():
    tutorials_path = '/Users/chestercurme/repos/langchain/docs/docs/tutorials/'
    for filename in os.listdir(tutorials_path):
        file_path = os.path.join(tutorials_path, filename)
        if filename.endswith('.mdx'):
            add_or_update_frontmatter_mdx(file_path)
            print(f'Updated {filename}')
        elif filename.endswith('.ipynb'):
            add_or_update_frontmatter_ipynb(file_path)
            print(f'Updated {filename}')
```

